script:
// Countdown (ds-metrics §14 — CountdownLabel): formatDuration(until − env.now) in `font` (default title, el16) + optional
// caption label (caption, el9), gap xs; env.now ticks every second while read. `expire` fires once when the time is
// up: a zero-size sentinel appears when nothing is left (also right away if `until` is already past).
param until: number
param format: "hms" | "ms" | "dhms" = "hms"
param label: string = ""
param font: textStyle = @type.title
event expire
let left = max(until - env.now, 0)
